$targetDir = "f:\Fallout\images\note_extracted\brotherhood-of-steel\"
if (!(Test-Path $targetDir)) { New-Item -ItemType Directory -Path $targetDir }

foreach ($img in $images) {
    $dest = Join-Path $targetDir $img.name
    Write-Host "Downloading $($img.name)..."
    Invoke-WebRequest -Uri $img.url -OutFile $dest
}
